def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp_dir(dx, dy):
        if dx > 1:
            dx = 1
        elif dx < -1:
            dx = -1
        if dy > 1:
            dy = 1
        elif dy < -1:
            dy = -1
        return [dx, dy]

    def pos(v, default=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position"), (0, 0))
    opp_pos = pos(observation.get("opponent_position"), self_pos)

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return clamp_dir(sgn(opp_pos[0] - self_pos[0]), sgn(opp_pos[1] - self_pos[1]))

        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = None
        best = None
        for c in corners:
            d = manhattan(c, opp_pos)
            if best is None or d > best:
                best = d
                target = c
        if target is None:
            return [0, 0]
        return clamp_dir(sgn(target[0] - self_pos[0]), sgn(target[1] - self_pos[1]))

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "neutral_cells", "frontier_cells"):
            items = observation.get(key) or []
            for item in items:
                p = pos(item)
                if p is not None:
                    candidates.append(p)

