                    best_target = t
            return clamp_dir(sgn(best_target[0] - self_pos[0]), sgn(best_target[1] - self_pos[1]))

        return clamp_dir(sgn(opp_pos[0] - self_pos[0]), sgn(opp_pos[1] - self_pos[1]))

    resources = []
    for key in ("resources", "resource_positions", "targets", "food"):
        items = observation.get(key) or []
        for item in items:
            p = pos(item)
            if p is not None:
                resources.append(p)

    if resources:
        best_target = None
        best_score = None
        for t in resources:
            d_self = manhattan(self_pos, t)
            d_opp = manhattan(opp_pos, t)
            score = d_self * 2 - d_opp
